  ru: seed.ru,
  uk: seed.uk,
  es: seed.es,
  'pt-BR': seed.sourceLocales['pt-BR'],
  vi: seed.sourceLocales.vi,
  tr: seed.sourceLocales.tr,
  pl: seed.sourceLocales.pl,
  sourceLocales: seed.sourceLocales,
  explanationRu: `${seed.en} = ${seed.meaningRu}. Употребляется в кино, сериалах и обычной живой речи, ${seed.contextRu}. Модель: готовая реплика, которую можно сказать целиком. Пример: ${seed.exampleEn} — ${seed.exampleRu}`,
  explanationUk: `${seed.en} = ${seed.meaningUk}. Уживається в кіно, серіалах і звичайній живій мові, ${seed.contextUk}. Модель: готова репліка, яку можна сказати цілком. Приклад: ${seed.exampleEn} — ${seed.exampleUk}`,
  explanationEs: `${seed.en} = ${seed.meaningEs}. Se usa en peliculas, series y habla cotidiana, ${seed.contextEs}. Patron: frase lista para decir completa. Ejemplo: ${seed.exampleEn} — ${seed.exampleEs}`,
  exampleEn: seed.exampleEn,
